window.AUTH=window.AUTH||{};window.AUTH["25-197"]={"d":"25-197","id":"2025/25-197","n":"T. M. v. University of Maryland Medical System Corporation","briefs":[{"k":"petitioner","label":"Brief of petitioner T.M.","date":"2026-01-14","url":"https://www.supremecourt.gov/DocketPDF/25/25-197/391713/20260114130929641_25-197_petbr.pdf","side":"pet","n":73},{"k":"respondent","label":"Brief of respondents University of Maryland Medical System Corporation, et al.","date":"2026-02-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-197/396216/20260213112320341_TM%20v.%20UMM%20Merits%20Brief.pdf","side":"res","n":65},{"k":"reply","label":"Reply of petitioner T.M.","date":"2026-03-16","url":"https://www.supremecourt.gov/DocketPDF/25/25-197/401296/20260319113423719_25-197_reply.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us2r49_mlho.pdf","tr":true,"items":[{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Allen v. Milligan","cite":"599 U.S. 1","y":2023,"id":"2022/21-1086","sc":1,"sum":"Plaintiffs demonstrated a reasonable likelihood of success on their claim that the districting plan adopted by the State of Alabama for its 2022 congressional elections likely violated §2 of the Voting Rights Act, 52 U. S. C. §10301.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46"}},{"t":"case","label":"Ames v. Kansas ex rel. Johnston","cite":"111 U.S. 449","y":1884,"id":"scdb/1883-237","sc":1,"sum":"Constitutional Law — Quo Warranto — Removal of Causes — Statutes.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"op":2,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"ASARCO Inc. v. Kadish","cite":"490 U.S. 605","y":1989,"id":"1988/87-1661","sc":1,"sum":"The judgment is affirmed. 155 Ariz. 484, 747 P. 2d 1183, affirmed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts I, II-A, II-B-2, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29-31","1":"23"}},{"t":"case","label":"Biden v. Texas","cite":"597 U.S. 785","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34","1":"35"}},{"t":"case","label":"Blythe v. Hinckley","cite":"173 U.S. 501","y":1899,"id":"scdb/1898-107","sc":1,"sum":"It appearing from the opinion of the Circuit Judge that the various bills in this case were dismissed on the grouiids: (1) That the jurisdiction of the Circuit Court could not be maintained because the state court, in the exercise of its general jurisdiction, determined the eligibility of the defendant Florence Blythe to inherit an estate which that court was called upon to distribute under the laws of the State, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22","2":"12"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne International Drilling Co.","cite":"581 U.S. 170","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/170/","sc":1,"by":{"0":"39"}},{"t":"case","label":"Chicago & Alton Railroad Co. v. Wiggins Ferry Co.","cite":"108 U.S. 18","y":1883,"id":"scdb/1882-118","sc":1,"sum":"this is a suit begun in a State court of Missouri'by the Wig-' gins Perry Company, an Illinois corporation,- against the-Chicago & Alton Railroad Company, another Illinois corporation, to recover damages for the breach of a contract by which, as is alleged, the railroad'company bound itself not to employ any other means than the ferry company’s ferry for the transportation of passengers and freight, coming and going …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Cipollone v. Liggett Group, Inc.","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Colorado River Water Conservation District v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"op":4,"ar":1,"sum":"In order to manage the allocation of water and to resolve conflicting claims thereto, Colorado enacted legislation under which the State is divided into seven Water Divisions, in each of which a procedure is established for the settlement of water claims on a continuous basis. A State Engineer is charged with responsibility for administering the distribution of state waters. Seeking adjudication of reserved rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 42, 43","1":"14, 41","2":"14"}},{"t":"case","label":"Cox Broadcasting Corp. v. Cohn","cite":"420 U.S. 469","y":1975,"id":"1974/73-938","sc":1,"op":1,"ar":1,"sum":"Describing four sets of circumstances within the Court's “pragmatic approach” to fnality.","sumSrc":"opinion","by":{"0":"30"}},{"t":"case","label":"Direct Marketing Association v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"0":"38, 39","2":"10"}},{"t":"case","label":"District of Columbia Court of Appeals v. Feldman","cite":"460 U.S. 462","y":1983,"id":"1982/81-1335","sc":1,"op":6,"sum":"Respondents filed petitions in the District of Columbia Court of Appeals asking for waivers of that court's District of Columbia Bar admission rule that requires applicants to have graduated from a law school approved by the American Bar Association. The court issued per curiam orders denying the petitions. Respondents then filed complaints in the United States District Court for the District of Columbia, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 5, 7-9, 14-15, 17, 19-20, 23-29, 31-33, 35-36, 43, 45","1":"2, 8-13, 15-25, 27-29, 32-38, 40-45","2":"1-11, 15-22"}},{"t":"case","label":"Dodson v. University of Arkansas for Medical Sciences","cite":"601 F.3d 750","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/601/750/","by":{"0":"37","1":"36"}},{"t":"case","label":"Doe v. University of Maryland Medical System Corp.","cite":"2025 WL 3553026","y":2025,"court":"4th Cir. Dec. 11","op":1,"by":{"0":"10","1":"3-4, 9"}},{"t":"case","label":"Earle v. McVeigh","cite":"91 U.S. 503","y":1876,"id":"scdb/1875-094","sc":1,"by":{"0":"33","1":"32-33","2":"11"}},{"t":"case","label":"Exxon Mobil Corp. v. Saudi Basic Industries Corp.","cite":"544 U.S. 280","y":2005,"id":"2004/03-1696","sc":1,"op":38,"sum":"The Court held that the the Third Circuit \"misperceived the narrow ground occupied by Rooker-Feldman.\" That doctrine was confined to cases brought by state-court losers complaining of state-court judgments made before the federal district court proceedings began and inviting district court rejection of those judgments.","sumSrc":"Oyez","by":{"0":"3, 5, 8-9, 14-15, 17, 19-20, 23, 25-29, 34-37, 42-46","1":"2, 8-10, 13, 16-22, 25, 27, 29, 34, 41","2":"1-8, 12, 13, 17, 20"}},{"t":"case","label":"Fay v. Noia","cite":"372 U.S. 391","y":1963,"id":"1962/84","sc":1,"sum":"The judgment of the Court of Appeals is affirmed on other grounds.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","1":"34","2":"13"}},{"t":"case","label":"Federal Bureau of Investigation v. Fikre","cite":"601 U.S. 234","y":2024,"id":"2023/22-1178","sc":1,"sum":"The Government failed to meet its burden to demonstrate that Mr. Fikre’s removal from the Government’s No Fly List mooted his 42 U. S. C. §1983 case because its declaration did not disclose the conduct that landed Mr. Fikre on the No Fly List and did not ensure that he would not be placed back on the list for engaging in the same or similar conduct in the future.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6","1":"14"}},{"t":"case","label":"Feldman v. Gardner","cite":"661 F.2d 1295","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/661/1295/","by":{"0":"24"}},{"t":"case","label":"Fishgold v. Sullivan Drydock & Repair Corp.","cite":"328 U.S. 275","y":1946,"id":"scdb/1945-102","sc":1,"sum":"After serving in the Army and receiving an honorable discharge, petitioner was reinstated in his former position pursuant to § 8 (a) of the Selective Training and Service Act of 1940. Subsequently, when there was not enough work to keep all employees busy, he was laid off temporarily on nine days while non-veterans with higher shop seniorities were permitted to work; but he was given work when enough became …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Forsyth v. Hammond","cite":"166 U.S. 506","y":1897,"id":"scdb/1896-159","sc":1,"sum":"Under the judiciary act of March 3, 1891, c. 517, the power of this court in certiorari extends to every case pending in the Circuit Courts of Appeals and may be exercised at any time during such pendency, provided the case is one which, but for this provision of the statute, would be finally determined in that court.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Fort Bend County v. Davis","cite":"587 U.S. 541","y":2019,"id":"2018/18-525","sc":1,"sum":"The charge-filing precondition to suit set out in Title VII of the Civil Rights Act of 1964 is not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Gilbank v. Wood County Department of Human Services","cite":"111 F.4th 754","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/111/754/","op":1,"by":{"0":"37","1":"36","2":"9"}},{"t":"case","label":"Great Western Mining & Mineral Co. v. Fox Rothschild LLP","cite":"615 F.3d 159","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/615/159/","by":{"0":"37","1":"36"}},{"t":"case","label":"Griffith v. Bank of New York","cite":"147 F.2d 899","y":1945,"url":"https://www.courtlistener.com/c/F.2d/147/899/","by":{"0":"33","1":"33"}},{"t":"case","label":"Growe v. Emison","cite":"507 U.S. 25","y":1993,"id":"1992/91-1420","sc":1,"sum":"Shortly after a group of Minnesota voters filed a state-court action against the Minnesota Secretary of State and other election officials, appellee voters filed a similar action against essentially the same officials in the Federal District Court. Both suits alleged that, in light of the 1990 census results, the State's congressional and legislative districts were malapportioned, in violation of the Federal and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Hadzi-Tanovic v. Johnson","cite":"62 F.4th 394","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/62/394/","op":1,"sum":"Stating that “we never … ask whether the relief the plaintiff seeks would reverse or undo the state court judgment”.","sumSrc":"brief:1","by":{"0":"37","1":"36, 43"}},{"t":"case","label":"Hamer v. Neighborhood Housing Services of Chicago","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Hawaii v. Office of Hawaiian Affairs","cite":"556 U.S. 163","y":2009,"id":"2008/07-1372","sc":1,"sum":"The Court held that the Apology Resolution did not restrict Hawaii's sovereign authority to transfer publicly held land for private development.","sumSrc":"Oyez","by":{"0":"20, 29"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":1,"sum":"Explaining Rooker-Feldman solely as an inference from § 1257.","sumSrc":"opinion","by":{"0":"39"}},{"t":"case","label":"Herr v. United States Forest Service","cite":"803 F.3d 809","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/809/","by":{"0":"38"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"0":"39","2":"10"}},{"t":"case","label":"Hoblock v. Albany County Board of Elections","cite":"422 F.3d 77","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/422/77/","op":1,"by":{"0":"37","1":"36"}},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"sum":"This decision overrules that portion of House v. Mayo, 324 U.S. 42, 44 (1945) (per curiam), which held that the Court lacks statutory certiorari jurisdiction to review denials of certificates of probable cause.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Hovey v. Elliott","cite":"167 U.S. 409","y":1897,"id":"scdb/1896-208","sc":1,"sum":"It is not within the power of the Supreme Court of the District of Columbia to order the answer of the defendant in a chancery suit pending in that court to be stricken from the files, and a decree to be entered that the bill be taken pro confesso against him, simply because he was held to be guilty of contempt in neglecting to pay into.court money held by him which was the subject of controversy in the suit, and …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33","1":"32-33"}},{"t":"case","label":"Hunter v. McMahon","cite":"75 F.4th 62","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/75/62/","op":5,"by":{"0":"9, 37","1":"42","2":"9"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Janus v. State, County & Municipal Employees","cite":"585 U.S. 878","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/878/","sc":1,"by":{"0":"46"}},{"t":"case","label":"Jefferson v. City of Tarrant","cite":"522 U.S. 75","y":1997,"id":"1997/96-957","sc":1,"sum":"In an 8-1 decision the Court found that it lacked jurisdiction. The opinion by Justice Ruth Bader Ginsburg held that the Court could not rule until the Alabama Supreme Court proceedings were completed and a final decision handed down. The case was dismissed.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Johnson v. De Grandy","cite":"512 U.S. 997","y":1994,"id":"1993/92-519","sc":1,"op":2,"sum":"In these consolidated cases, a group of Hispanic voters, a group of black voters, and the Federal Government claim that Florida's reapportionment plan for the State's single-member Senate and House districts (SJR 2-G) unlawfully dilutes the voting strength of Hispanics and blacks in the Dade County area, in violation of §2 of the Voting Rights Act of 1965. The State Supreme Court, in a review required by the State …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"28"}},{"t":"case","label":"Kremer v. Chemical Construction Corp.","cite":"456 U.S. 461","y":1982,"id":"1981/80-6045","sc":1,"sum":"The District Court was required under 28 U. S. C. § 1738 to give preclusive effect to the state court decision upholding the state administrative agency's rejection of the employment discrimination claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Lance v. Dennis","cite":"546 U.S. 459","y":2006,"id":"2005/05-555","sc":1,"op":6,"ar":3,"sum":"The Court held that \"The Rooker-Feldman doctrine does not bar actions by nonparties to the earlier state-court judgment simply because [...] they could be considered in privity with a party to the judgment.\" Since Lance was not a party to the state-court suit, and was in no position to appeal the Colorado Supreme Court's decision, the District Court had jurisdiction to hear the case.","sumSrc":"Oyez","by":{"0":"8-9, 20, 28-29","1":"22"}},{"t":"case","label":"36, 42, 45 Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"case","label":"Lucky Brand Dungarees, Inc. v. Marcel Fashions Group, Inc.","cite":"590 U.S. 405","y":2020,"id":"2019/18-1086","sc":1,"op":1,"sum":"Explaining that issue preclusion “precludes a party from relitigating an issue actually decided in a prior case and necessary to the judgment”.","sumSrc":"opinion","by":{"0":"41","1":"42","2":"18"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Michigan v. Long","cite":"463 U.S. 1032","y":1983,"id":"1982/82-256","sc":1,"sum":"The Court, after admitting that it had not developed \"a satisfying and consistent approach\" regarding lower court references to independent state grounds, held that it had jurisdiction in the case. The Court held that when state court decisions appeared to rest primarily on federal law, it would infer that state courts believed that federal law required them to do so.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Middlesex County Ethics Committee v. Garden State Bar Association","cite":"457 U.S. 423","y":1984,"id":"1981/81-460","sc":1,"sum":"The federal courts should abstain from interfering with the ongoing disciplinary proceedings within the jurisdiction of the New Jersey Supreme Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"O’Brien v. Hanover Insurance Co.","cite":"692 N.E.2d 39","y":1998,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/692/39/","by":{"0":"41"}},{"t":"case","label":"Parsons Steel, Inc. v. First Alabama Bank","cite":"474 U.S. 518","y":1986,"id":"1985/84-1616","sc":1,"op":2,"sum":"Petitioners sued respondents in an Alabama state court, alleging that respondent bank had fraudulently induced petitioner individuals to permit a third person to take control of a subsidiary of petitioner corporation and eventually to obtain complete ownership. Subsequently, the subsidiary was adjudicated an involuntary bankrupt. Petitioners then sued the bank in Federal District Court, alleging that the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"33","2":"10"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Pierce County v. Guillen","cite":"537 U.S. 129","y":2003,"id":"2002/01-1229","sc":1,"sum":"The Court held that both the original program and its subsequent amendments fall within Congress's Commerce Clause power to \"'regulate the use of the channels of interstate commerce'\" and \"'to regulate and protect the instrumentalities of interstate commerce.'\" The Court concluded that, because Congress could reasonably believe that adopting a measure eliminating an unforeseen side effect of the Program's information-gathering requirement would result in greater safety on the nation's roads, the legislation was aimed at improving safety in the channels of commerce and increasing protections for the instrumentalities of interstate commerce.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Riley v. Bondi","cite":"606 U.S. 259","y":2025,"id":"2024/23-1270","sc":1,"sum":"Order from the Board of Immigration Appeals denying deferral of removal in “withholding only” proceeding is not a “final order of removal” under 8 U. S. C. §1252(b)(1); the 30-day filing deadline to challenge a final order of removal under §1252(b)(1) is a claims-processing rule, not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Reed v. Goertz","cite":"598 U.S. 230","y":2023,"id":"2022/21-442","sc":1,"op":6,"ar":1,"sum":"When a prisoner pursues state post-conviction DNA testing through the state-provided litigation process, the statute of limitations for a 42 U. S. C. §1983 procedural due process claim begins to run when the state litigation ends, in this case when the Texas Court of Criminal Appeals denied Reed’s motion for rehearing.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36","1":"13-14, 22, 25, 28"}},{"t":"case","label":"RLR Investments, LLC v. City of Pigeon Forge","cite":"4 F.4th 380","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/4/380/","op":2,"by":{"0":"37"}},{"t":"case","label":"Scotland County v. Hill","cite":"132 U.S. 107","y":1889,"id":"scdb/1889-014","sc":1,"sum":"The negotiable security of a municipal corporation, invalid in the hands of the' original holder by reason of an irregularity in its issue to which he was a party, but which becomes valid in the hands of an innocent purchaser for value without knowledge or notice of the irregularity, remains valid when acquired by another purchaser for value, who was no party to the irregularity, but who, at the time of his …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Sebelius v. Auburn Regional Medical Center","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Skinner v. Switzer","cite":"562 U.S. 521","y":2011,"id":"2010/09-9000","sc":1,"op":3,"ar":3,"sum":"Explaining Rooker-Feldman solely as an inference from § 1257.","sumSrc":"opinion","by":{"0":"9, 29, 31, 36","1":"22-23","2":"6"}},{"t":"case","label":"Smith v. Apple","cite":"264 U.S. 274","y":1924,"id":"scdb/1923-086","sc":1,"ar":2,"sum":"1. Where a District Court dismisses a suit upon the specific ground of want of jurisdiction, this Court, upon a sufficient certificate, acquires jurisdiction of a direct appeal, and whatever the reason assigned by the District Court for the supposed want of jurisdiction, must determine whether that cpurt had and should have exercised the jurisdiction thus denied.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22","2":"11"}},{"t":"case","label":"Sprint Communications, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"op":1,"sum":"The Court held that a federal court does not need to abstain from deciding a case only because there is a case in state court that deals with the same subject matter.","sumSrc":"Oyez","by":{"0":"42","1":"41"}},{"t":"case","label":"Stop the Beach Renourishment, Inc. v. Florida Department of Environmental Protection","cite":"560 U.S. 702","y":2010,"id":"2009/08-1151","sc":1,"sum":"The Court held that a ruling on littoral (\"on or near the shore\") takings by the Florida Supreme Court did not cause a judicial takings violation of the Fifth or Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"36","1":"22"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"0":"41","1":"41"}},{"t":"case","label":"United States v. Addonizio","cite":"442 U.S. 178","y":1979,"id":"1978/78-156","sc":1,"sum":"A federal prisoner's allegation that a postsentencing change in the policies of the United States Parole Commission has prolonged his actual imprisonment beyond the period intended by the sentencing judge will not support a collateral attack on the original sentence under 28 U. S. C. § 2255.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","1":"34"}},{"t":"case","label":"United States v. Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"VanderKodde v. Mary Jane M. Elliott, P.C.","cite":"951 F.3d 397","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/951/397/","op":2,"ar":1,"by":{"0":"4, 7, 36","1":"36","2":"7"}},{"t":"case","label":"Verizon Maryland, Inc. v. Public Service Commission of Maryland","cite":"535 U.S. 635","y":2002,"id":"2001/00-1531","sc":1,"op":3,"ar":4,"sum":"The Court held that the district court had jurisdiction, so as to review the Commission's order for compliance with federal law, to entertain the suit because resolution of the LEC's claim turned on whether the Act, or an FCC ruling issued thereunder, precluded the state commission from ordering payment of reciprocal compensation.","sumSrc":"Oyez","by":{"0":"33","1":"25, 27","2":"7, 8, 12"}},{"t":"case","label":"Wall v. Kholi","cite":"562 U.S. 545","y":2011,"id":"2010/09-868","sc":1,"op":1,"sum":"Explaining Rooker-Feldman solely as an inference from § 1257.","sumSrc":"opinion","by":{"0":"33","1":"34"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"op":3,"sum":"The Quiet Title Act’s 12-year statute of limitations, 28 U. S. C. §2409a(g), is a nonjurisdictional claims-processing rule.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39, 46"}},{"t":"case","label":"Willy v. Coastal Corp.","cite":"503 U.S. 131","y":1992,"id":"1991/90-1150","sc":1,"sum":"A court may impose Rule 11 sanctions in a case in which the district court is later determined to be without subject-matter jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"op":3,"ar":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"const","label":"Article III, Section 2, Clause 2","clauses":[["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make.","by":{"0":"6"}},{"t":"case","label":"Almendarez v. City of Coppell","cite":"2024 WL 992191","y":2024,"court":"N.D. Tex. Mar. 6","by":{"1":"37"}},{"t":"case","label":"Atl. Coast Line R. Co. v. Bhd. of Locomotive Eng’rs","cite":"398 U.S. 281","y":1970,"id":"1969/477","sc":1,"op":3,"sum":"The federal injunction was not justified under the exceptions in § 2283 and thus was improperly issued in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13-14, 25, 28, 39"}},{"t":"case","label":"Chick Kam Choo v. Exxon Corp.","cite":"486 U.S. 140","y":1988,"id":"1987/87-505","sc":1,"sum":"Because the District Court's injunction barring the state court proceedings is broader than is necessary \"to protect or effectuate\" that court's 1980 judgment dismissing petitioner's lawsuit from federal court, this case must be remanded for the entry of a more narrowly tailored order.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 27, 39"}},{"t":"case","label":"Federación de Maestros de P.R. v. Junta de Relaciones del Trabajo de P.R.","cite":"410 F.3d 17","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/410/17/","op":6,"sum":"Describing test to determine whether proceedings have functionally “ended”.","sumSrc":"opinion","by":{"1":"24, 37-38"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"sum":"The unanimous Court held that the Act's creation of an appellate panel, charged with reviewing all second or successive habeas applications, is not unconstitutional. The Act simply transfers the duty of habeas review from the district courts to an appellate panel.","sumSrc":"Oyez","by":{"1":"30","2":"13, 15"}},{"t":"case","label":"Green v. Jefferson Cnty. Comm’n","cite":"563 F.3d 1243","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/563/1243/","by":{"1":"42"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"1":"29-30"}},{"t":"case","label":"Guttman v. Khalsa","cite":"446 F.3d 1027","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/446/1027/","op":2,"by":{"1":"42"}},{"t":"case","label":"Jennings v. Stephens","cite":"574 U.S. 271","y":2015,"id":"2014/13-7211","sc":1,"sum":"The Court held that a federal habeas petitioner who prevailed in district court does not need to file a separate certificate of appealability to respond to the state's appeal.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Johnson v. Orr","cite":"551 F.3d 564","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/551/564/","by":{"1":"18"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Malhan v. Sec’y U.S. Dep’t of State","cite":"938 F.3d 453","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/938/453/","op":3,"by":{"1":"24, 37, 42"}},{"t":"case","label":"Miller v. Dunn","cite":"35 F.4th 1007","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/35/1007/","op":1,"by":{"1":"42"}},{"t":"case","label":"Moses H. Cone Mem’l Hosp. v. Mercury Constr. Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"op":3,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Ortiz v. United States","cite":"585 U.S. 427","y":2018,"id":"2017/16-1423","sc":1,"sum":"The Court held that it has jurisdiction to review the CAAF's decisions and that Judge Martin T. Mitchell’s simultaneous service on the US Court of Military Commission Review (CMCR) and the US Air Force Court of Criminal Appeals (AFCCA) does not violate the Appointments Clause or 10 U.S.C. § 973(b)(2)(A).","sumSrc":"Oyez","by":{"1":"14, 28","2":"9, 10"}},{"t":"case","label":"Parker v. Lyons","cite":"757 F.3d 701","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/701/","op":1,"by":{"1":"42-43"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34-35"}},{"t":"case","label":"Radio Station WOW, Inc. v. Johnson","cite":"326 U.S. 120","y":1945,"id":"scdb/1944-027","sc":1,"op":2,"sum":"1. A state court decree otherwise \"final\" for purposes of review by this Court is none the less so because it orders also an accounting of profits, where such accounting can not give rise to a federal question. Judicial Code, § 237.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Republic Nat. Gas Co. v. Oklahoma","cite":"334 U.S. 62","y":1948,"id":"scdb/1947-075","sc":1,"sum":"The judgment of the State Supreme Court was not 'final\" within the meaning of § 237 of'the Judicial Code, and this Court is therefore without jurisdiction of an appeal therefrom. Pp. 62-72. 198 Okla. 350,.180 P. 2d 1009, appeal dismissed. An order of the State Corporation Commission of Oklahoma, directing the appellant to take gas ratably from another producer in the same field, was sustained by the State Supreme …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Rooker v. Fid. Tr. Co.","cite":"263 U.S. 413","y":1923,"id":"scdb/1923-051","sc":1,"op":14,"sum":"1. Where a judgment has been rendered, after due hearing, by a state trial court, with jurisdiction of the subject matter and parties, and affirmed by the state Supreme Court, the only resort under the","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 8-13, 15-29, 32, 34-38, 40-45","2":"1-12, 15-22"}},{"t":"case","label":"Rooker v. Fid. Tr. Co.","cite":"131 N.E. 769","y":1921,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E./131/769/","op":3,"by":{"1":"15"}},{"t":"case","label":"Royal Canin U. S. A., Inc. v. Wullschleger","cite":"604 U.S. 22","y":2025,"id":"2024/23-677","sc":1,"sum":"When a plaintiff amends her complaint to delete the federal-law claims that enabled removal to federal court, leaving only state-law claims behind, the federal court loses supplemental jurisdiction over the state claims, and the case must be remanded to state court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"13","2":"14"}},{"t":"case","label":"Ruhrgas AG v. Marathon Oil Co.","cite":"526 U.S. 574","y":1999,"id":"1998/98-470","sc":1,"op":1,"sum":"The Court held that in cases removed from a state court to federal court there is \"no unyielding jurisdictional hierarchy requiring the federal court to adjudicate subject-matter jurisdiction before considering a challenge to personal jurisdiction.\" Customarily, however, a federal court would first resolve doubts about its jurisdiction over the subject matter.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Stanley v. City of Sanford","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"sum":"To prevail under 42 U. S. C. §12112(a), a plaintiff must plead and prove that she held or desired a job, and could perform its essential functions with or without reasonable accommodation, at the time of an employer’s alleged act of disability-based discrimination; the judgment of the Eleventh Circuit is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"44"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Stone v. Powell","cite":"428 U.S. 465","y":1976,"id":"1975/74-1055","sc":1,"sum":"In a 6-to-3 decision, the Court held that where states had provided opportunities for full and fair litigation of Fourth Amendment claims, the Constitution did not require the granting of federal habeas corpus relief. The Court also held that any additional benefits from considering search and seizure claims of state prisoners on collateral review would be small in relation to the costs.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Suter v. Stuckey","cite":"935 A.2d 731","y":2007,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/935/731/","by":{"1":"37"}},{"t":"case","label":"Toucey v. New York Life Ins. Co.","cite":"314 U.S. 118","y":1941,"id":"scdb/1941-006","sc":1,"sum":"Section 265 of the Judicial Code forbids a federal court to enjoin a proceeding in personam in a state court on the ground that the claim in controversy has been previously -adjudicated by the federal court. P. 129. 112 F. 2d 927 and 115 F. 2d 1, reversed. No. 16 came here on certiorari, 311 U. S. 643, to review the affirmance of a decree of injunction, 112 F. 2d 927. The decision below was affirmed here by an …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"sum":"Respondent's failure to make timely objection under the Florida contemporaneous-objection rule to the admission of his inculpatory statements, absent a showing of cause for the noncompliance and some showing of actual prejudice, bars federal habeas corpus review of his Miranda claim. Davis v. United States, 411 U. S. 233; Francis v. Henderson,425 U. S. 536.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Warner Chappell Music, Inc. v. Nealy","cite":"601 U.S. 366","y":2024,"id":"2023/22-1078","sc":1,"sum":"The Copyright Act entitles a copyright owner to obtain monetary relief for any timely infringement claim, no matter when the infringement occurred.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43-44"}},{"t":"case","label":"Wilkinson v. Dotson","cite":"544 U.S. 74","y":2005,"id":"2004/03-287","sc":1,"op":34,"sum":"Yes and No. In an 8-1 decision, the Court affirmed the appellate court and ruled that prisoners could use Section 1983 to challenge a state's parole procedures.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Wright v. West","cite":"505 U.S. 277","y":1992,"id":"1991/91-542","sc":1,"op":1,"sum":"The judgment is reversed, and the case is remanded. 931 F. 2d 262, reversed and remanded. JUSTICE THOMAS, joined by THE CMHEF JUSTICE and JUSTICE ScALiA, concluded that regardless of whether a federal habeas court should review state-court applications of law to fact deferentially or de novo, the trial record contains more than enough evidence to support West's conviction. Jackson repeatedly emphasizes the deference …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"usc","label":"25 U.S.C. § 1914","url":"https://www.law.cornell.edu/uscode/text/25/1914","stext":{"head":"§1914. Petition to court of competent jurisdiction to invalidate action upon showing of certain violations","paras":[[0,"Any Indian child who is the subject of any action for foster care placement or termination of parental rights under State law, any parent or Indian custodian from whose custody such child was removed, and the Indian child's tribe may petition any court of competent jurisdiction to invalidate such action upon a showing that such action violated any provision of sections 1911, 1912, and 1913 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1914?type=usc&year=mostrecent&link-type=html"},"head":"§1914. Petition to court of competent jurisdiction to invalidate action upon showing of certain violations","tname":"Indians","by":{"1":"31","2":"14"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"1":"28, 31, 42"}},{"t":"case","label":"Behr v. Campbell","cite":"8 F.4th 1206","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/8/1206/","by":{"2":"8"}},{"t":"case","label":"Bowe v. United States","cite":"146 S. Ct. 447","y":2026,"id":"2025/24-5438","sc":1,"sum":"Title 28 U. S. C. §2244(b)(3)(E) does not bar this Court’s review of a federal prisoner’s request to file a second or successive §2255 motion for postconviction relief, and §2244(b)(1) does not apply to second or successive motions filed under §2255(h) by federal prisoners challenging their convictions or sentences.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14"}},{"t":"case","label":"Breuer v. Jim’s Concrete of Brevard, Inc.","cite":"538 U.S. 691","y":2003,"id":"2002/02-337","sc":1,"sum":"The Court held that the FLSA does not bar removal of a suit from state to federal court, thus Breuer's case was properly removed under section 1441.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Brown v. Davenport","cite":"596 U.S. 118","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"sum":"1. Section 10 of the Administrative Procedure Act (APA), providing generally for judicial review of actions of federal administrative agencies by persons aggrieved by such actions, does not afford an implied grant to district courts of subject-matter jurisdiction to review a decision of the Secretary of Health, Education, and Welfare not to reopen a previously adjudicated claim for social security benefits. An …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Freeman v. Bee Machine Co.","cite":"319 U.S. 448","y":1943,"id":"scdb/1942-091","sc":1,"sum":"that the defendant was \"found\" within the district so as to give the District Court power to allow the complaint to be amended by adding a cause of action under § 4 of the Clayton Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"HPIL Holding, Inc. v. Zhang","cite":"2026 WL 636728","y":2026,"court":"6th Cir. Mar. 6","ar":1,"by":{"2":"17"}},{"t":"case","label":"Huntington v. Laidley","cite":"176 U.S. 668","y":1900,"id":"scdb/1899-147","sc":1,"ar":1,"sum":"In order to maintain a direct appeal to this court from the Circuit Court of the United States under the act of March 3, 1891, c. 517, § 5, as to the jurisdiction of the court below, the record must distinctly and unequivocally show that that court sends up for consideration a single and definite question of its jurisdiction; but this may appear either by the terms of the decree appealed from and of the order …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"11, 12"}},{"t":"case","label":"Lebron v. National Railroad Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Schlesinger v. Councilman","cite":"420 U.S. 738","y":1975,"id":"1974/73-662","sc":1,"sum":"After court-martial charges were preferred against respondent Army captain for the sale, transfer, and possession of marihuana, he brought suit in Federal District Court to enjoin petitioner military authorities from proceeding with the court-martial. The District Court granted a permanent injunction, and the Court of Appeals affirmed, on the ground that the offenses charged were not \"service connected\" and hence …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Shinn v. Ramirez","cite":"596 U.S. 366","y":2022,"id":"2021/20-1009","sc":1,"sum":"Under 28 U. S. C. §2254(e)(2), a federal habeas court may not conduct an evidentiary hearing or otherwise consider evidence beyond the state-court record based on the ineffective assistance of state postconviction counsel.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"15"}},{"t":"case","label":"Simon v. Southern Railway Co.","cite":"236 U.S. 115","y":1915,"id":"scdb/1914-247","sc":1,"ar":1,"sum":"United States courts by virtue of their general equity powers have jurisdiction to enjoin the enforcement of a judgment obtained by fraud or without service.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"11, 16"}},{"t":"case","label":"United States v. Coe","cite":"155 U.S. 76","y":1894,"id":"scdb/1894-007","sc":1,"op":1,"sum":"The provisions in the act of March 3, 1891, c. 539, 26 S'tat. 854, “ to establish a court of private land claims and to provide for the settlement of private land claims in certain States and Territories,” authorizing this court to amend the proceedings of the court below, and to cause additional testimony to be taken, are not mandatory, but only empower the court to direct further proofs, and to amend the record, …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Wells Fargo & Co. v. Taylor","cite":"254 U.S. 175","y":1920,"id":"scdb/1920-018","sc":1,"ar":1,"sum":"1. Where.the District Court sustains a bill in equity against a demurrer and upon final hearing renders a decree for the plaintiff, a reversal ordered by the Circuit Court of Appeals purely because of an amendable deficiency of the bill and unaccompanied by any direction that the bill be dismissed or implication forbidding its amendment, leaves the District Court free to permit the amendment; and the fact that the …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"11"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","subs":["(a)"],"stext":{"head":"§1257. State courts; certiorari","paras":[[0,"(a) Final judgments or decrees rendered by the highest court of a State in which a decision could be had, may be reviewed by the Supreme Court by writ of certiorari where the validity of a treaty or statute of the United States is drawn in question or where the validity of a statute of any State is drawn in question on the ground of its being repugnant to the Constitution, treaties, or laws of the United States, or where any title, right, privilege, or immunity is specially set up or claimed under the Constitution or the treaties or statutes of, or any commission held or authority exercised under, the United States."],[0,"(b) For the purposes of this section, the term \"highest court of a State\" includes the District of Columbia Court of Appeals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1257?type=usc&year=mostrecent&link-type=html"},"op":33,"ar":17,"head":"§1257. State courts; certiorari","tname":"Judiciary and Judicial Procedure","by":{"2":"1-4, 6-9, 11, 15, 19, 20, 6, 8"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"op":30,"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"2":"6-8, 14, 16"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1332. Diversity of citizenship; amount in controversy; costs","tname":"Judiciary and Judicial Procedure","by":{"2":"14, 16"}},{"t":"rule","label":"Fed. R. App. P. 10","url":"https://www.law.cornell.edu/rules/frap/rule_10","by":{"2":"10"}}]};